@media (prefers-color-scheme: dark) {
  :root {
    --color-paper: oklch(16.5% 0.014 272);
    --color-paper-2: oklch(13.5% 0.012 272);
    --color-paper-3: oklch(25% 0.018 272);
    --color-surface: oklch(20.5% 0.016 272);
    --color-ink: oklch(94% 0.008 272);
    --color-ink-2: oklch(82% 0.014 272);
    --color-muted: oklch(71% 0.018 272);
    --color-rule: oklch(30% 0.016 272);
    --color-rule-2: oklch(39% 0.018 272);

    --color-accent: oklch(70% 0.150 277);
    --color-accent-hover: oklch(75% 0.130 277);
    --color-accent-edge: oklch(50% 0.170 277);
    --color-accent-text: oklch(80% 0.110 277);
    --color-accent-wash: oklch(28% 0.070 277);
    --color-accent-ink: oklch(16% 0.030 277);
    --color-focus: oklch(72% 0.150 277);

    --color-frozen: oklch(78% 0.090 215);
    --color-frozen-wash: oklch(26% 0.040 222);
    --color-error: oklch(72% 0.150 25);
    --color-error-wash: oklch(27% 0.060 25);

    --color-key-face: oklch(24% 0.018 272);
    --color-key-hover: oklch(28% 0.020 272);
    --color-key-edge: oklch(11% 0.012 272);

    --color-graphite: oklch(11.5% 0.012 268);
    --color-graphite-ink: oklch(92% 0.010 272);
    --color-graphite-accent: oklch(80% 0.100 277);

    --color-canvas-dot: oklch(32% 0.018 272);
    --color-edge: oklch(52% 0.025 272);
    --color-edge-active: oklch(72% 0.150 277);

    --shadow-card: inset 0 0 0 1px oklch(100% 0 0 / 0.02);
    --shadow-raised: 0 0 0 1px var(--color-rule-2);
    --shadow-key-press: inset 0 1px 2px oklch(0% 0 0 / 0.4);
  }
}

/* ---------- base ---------- */
*, *::before, *::after { box-sizing: border-box; }
html, body { overflow-x: clip; }
html { accent-color: var(--color-accent); scrollbar-color: var(--color-rule-2) var(--color-paper); -webkit-text-size-adjust: 100%; }
body {
  margin: 0; min-height: 100dvh; background: var(--color-paper); color: var(--color-ink);
  font-family: var(--font-body); font-size: var(--text-md); line-height: 1.6;
  word-break: keep-all; overflow-wrap: break-word; -webkit-font-smoothing: antialiased; caret-color: var(--color-accent);
}
::selection { background: color-mix(in oklab, var(--color-accent) 24%, transparent); color: var(--color-ink); }
:focus-visible { outline: 2px solid var(--color-focus); outline-offset: 2px; }
a { color: inherit; text-decoration-thickness: 1px; text-underline-offset: 0.18em; }
h1, h2, h3, h4 { margin: 0; font-family: var(--font-display); font-weight: 600; font-synthesis: none; letter-spacing: -0.012em; line-height: 1.3; overflow-wrap: break-word; min-width: 0; color: var(--color-ink); }
h1 { font-size: var(--text-2xl); text-wrap: balance; } h2 { font-size: var(--text-xl); text-wrap: balance; } h3 { font-size: var(--text-lg); } h4 { font-size: var(--text-md); }
p { margin: 0; text-wrap: pretty; }
ul, ol { margin: 0; }
img, video { max-width: 100%; height: auto; display: block; }
svg { flex: none; }
[hidden] { display: none !important; }
button, input, select, textarea { font: inherit; color: inherit; }
code, kbd, pre, .mono { font-family: var(--font-mono); }
.num { font-variant-numeric: tabular-nums; }
.visually-hidden { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* ---------- app shell ---------- */
.app-shell { min-height: 100dvh; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.app-main { width: 100%; max-width: var(--container); margin-inline: auto; padding: var(--space-lg) var(--gutter) var(--space-2xl); }
.app-main--full { max-width: none; padding: 0; }
.page-head { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: var(--space-md); margin-bottom: var(--space-lg); }
.page-head__text { display: grid; gap: var(--space-2xs); min-width: 0; }
.page-head__desc { color: var(--color-ink-2); max-width: 60ch; }

.app-header {
  position: sticky; top: 0; z-index: var(--z-sticky-nav);
  display: flex; align-items: center; gap: var(--space-lg);
  height: var(--header-h); padding-inline: var(--gutter);
  background: var(--color-paper); border-bottom: var(--rule-hair) solid var(--color-rule);
}
.app-brand { display: inline-flex; align-items: center; gap: var(--space-xs); border-radius: var(--radius-input); color: var(--color-ink); font-weight: 700; font-size: var(--text-md); line-height: 1; letter-spacing: -0.01em; text-decoration: none; white-space: nowrap; }
.app-brand img { width: 28px; height: 28px; }
.app-nav { min-width: 0; overflow-x: auto; scrollbar-width: none; }
.app-nav ul { display: flex; gap: var(--space-2xs); padding: 0; list-style: none; }
.app-nav a {
  display: inline-flex; align-items: center; min-height: var(--control-h-sm); padding: 0 var(--space-sm);
  border-radius: var(--radius-input); color: var(--color-ink-2); font-size: var(--text-sm); font-weight: 500; line-height: 1;
  text-decoration: none; white-space: nowrap;
  transition: color var(--dur-micro) var(--ease-out), background-color var(--dur-micro) var(--ease-out);
}
@media (hover: hover) { .app-nav a:hover { color: var(--color-ink); background: var(--color-paper-3); } }
.app-nav a:active { background: var(--color-rule); }
.app-nav a[aria-current="page"] { color: var(--color-accent-text); background: var(--color-accent-wash); }
.app-header__aside { margin-left: auto; color: var(--color-muted); font-size: var(--text-sm); white-space: nowrap; }
@media (max-width: 40rem) {
  :root { --gutter: 16px; }
  .app-header { gap: var(--space-sm); }
  .app-brand__name, .app-header__aside { display: none; }
}

/* ---------- buttons (keycaps) ---------- */
.btn {
  position: relative; display: inline-flex; align-items: center; justify-content: center; gap: var(--space-xs);
  min-height: var(--control-h); padding: 0 var(--space-md);
  border: var(--rule-hair) solid var(--color-rule-2); border-radius: var(--radius-input);
  background: var(--color-key-face); color: var(--color-ink); box-shadow: var(--shadow-key);
  font-family: var(--font-body); font-size: var(--text-sm); font-weight: 500; line-height: 1;
  white-space: nowrap; text-decoration: none; cursor: pointer;
  transition: transform var(--dur-micro) var(--ease-out), box-shadow var(--dur-micro) var(--ease-out), background-color var(--dur-micro) var(--ease-out);
}
.btn svg { width: 16px; height: 16px; }
@media (hover: hover) { .btn:hover { background: var(--color-key-hover); } }
.btn:active { transform: translateY(2px); box-shadow: var(--shadow-key-press); }
.btn:focus-visible { outline: 2px solid var(--color-focus); outline-offset: 2px; }
.btn:disabled, .btn[aria-disabled="true"] { opacity: 0.55; cursor: not-allowed; transform: none; box-shadow: none; }
.btn[aria-busy="true"] { cursor: progress; }

.btn--primary { background: var(--color-accent); border-color: var(--color-accent-edge); color: var(--color-accent-ink); box-shadow: var(--shadow-key-accent); }
@media (hover: hover) { .btn--primary:hover { background: var(--color-accent-hover); } }

.btn--ghost { background: transparent; border-color: transparent; box-shadow: none; color: var(--color-ink-2); }
@media (hover: hover) { .btn--ghost:hover { background: var(--color-paper-3); color: var(--color-ink); } }
.btn--ghost:active { transform: none; background: var(--color-rule); box-shadow: none; }

.btn--danger { color: var(--color-error); }
@media (hover: hover) { .btn--danger:hover { background: var(--color-error-wash); } }

.btn--sm { min-height: var(--control-h-sm); padding: 0 var(--space-sm); }
.btn--sm::after { content: ""; position: absolute; inset: calc(var(--space-2xs) * -1.5) 0; }
.btn--icon { padding: 0; width: var(--control-h); }
.btn--icon.btn--sm { width: var(--control-h-sm); }
.btn--icon.btn--sm::after { inset: calc(var(--space-2xs) * -1.5); }
.btn-row { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-xs); }

/* ---------- fields ---------- */
.field { display: grid; gap: var(--space-2xs); min-width: 0; }
.field__label { font-size: var(--text-sm); font-weight: 500; color: var(--color-ink); }
.field__help { min-height: 1lh; font-size: var(--text-sm); color: var(--color-muted); }
.field__error { min-height: 1lh; font-size: var(--text-sm); color: var(--color-error); }
.input, .textarea, .select {
  width: 100%; border: var(--rule-hair) solid var(--color-muted); border-radius: var(--radius-input);
  background: var(--color-surface); color: var(--color-ink); font-size: var(--text-md); line-height: 1.5;
  outline: 2px solid transparent; outline-offset: -2px;
  transition: background-color var(--dur-micro) var(--ease-out), border-color var(--dur-micro) var(--ease-out);
}
.input, .select { height: var(--control-h); padding: 0 var(--space-sm); }
.textarea { display: block; min-height: calc(var(--control-h) * 2.4); padding: var(--space-xs) var(--space-sm); resize: vertical; }
.textarea--code { font-family: var(--font-mono); font-size: var(--text-sm); line-height: 1.6; }
.input::placeholder, .textarea::placeholder { color: var(--color-muted); }
@media (hover: hover) { .input:hover, .textarea:hover, .select:hover { background: var(--color-paper); } }
.input:focus-visible, .textarea:focus-visible, .select:focus-visible { outline-color: var(--color-focus); border-color: var(--color-ink-2); }
.input[aria-invalid="true"], .textarea[aria-invalid="true"] { border-color: var(--color-error); }
.input:disabled, .textarea:disabled, .select:disabled { opacity: 0.55; cursor: not-allowed; background: var(--color-paper-2); }

/* ---------- choices (selectable chips) ---------- */
.choices { display: flex; flex-wrap: wrap; gap: var(--space-xs); min-width: 0; margin: 0; padding: 0; border: 0; }
.choices > legend { float: left; width: 100%; margin-bottom: var(--space-xs); padding: 0; font-size: var(--text-sm); font-weight: 500; }
.choices--stack { flex-direction: column; align-items: stretch; }
.chip {
  position: relative; display: inline-flex; align-items: center; gap: var(--space-xs);
  min-height: var(--control-h); padding: var(--space-xs) var(--space-md);
  border: var(--rule-hair) solid var(--color-rule-2); border-radius: var(--radius-input);
  background: var(--color-key-face); color: var(--color-ink); box-shadow: var(--shadow-key);
  font-size: var(--text-sm); line-height: 1.45; text-align: left; cursor: pointer;
  transition: transform var(--dur-micro) var(--ease-out), box-shadow var(--dur-micro) var(--ease-out), background-color var(--dur-micro) var(--ease-out), border-color var(--dur-micro) var(--ease-out);
}
.chip input { position: absolute; width: 1px; height: 1px; margin: 0; opacity: 0; pointer-events: none; }
.chip__check { width: 14px; height: 14px; opacity: 0; color: var(--color-accent-text); }
@media (hover: hover) { .chip:hover { background: var(--color-key-hover); border-color: var(--color-muted); } }
.chip:active { transform: translateY(2px); box-shadow: var(--shadow-key-press); }
.chip:has(input:checked), .chip[aria-pressed="true"] { transform: translateY(2px); box-shadow: var(--shadow-key-press); background: var(--color-accent-wash); border-color: var(--color-accent); color: var(--color-accent-text); }
.chip:has(input:checked) .chip__check, .chip[aria-pressed="true"] .chip__check { opacity: 1; }
.chip:focus-visible, .chip:has(input:focus-visible) { outline: 2px solid var(--color-focus); outline-offset: 2px; }
.chip:disabled, .chip:has(input:disabled) { opacity: 0.55; cursor: not-allowed; box-shadow: none; }

/* ---------- segmented toggle ---------- */
.seg { display: inline-flex; gap: var(--space-3xs); padding: var(--space-3xs); border-radius: var(--radius-input); background: var(--color-paper-3); }
.seg button {
  min-height: var(--control-h-sm); padding: 0 var(--space-sm); border: 0; border-radius: var(--radius-mark);
  background: transparent; color: var(--color-ink-2); font-size: var(--text-sm); font-weight: 500; line-height: 1; white-space: nowrap; cursor: pointer;
  transition: background-color var(--dur-micro) var(--ease-out), color var(--dur-micro) var(--ease-out);
}
@media (hover: hover) { .seg button:hover { color: var(--color-ink); } }
.seg button:active { background: var(--color-rule); }
.seg button[aria-pressed="true"] { background: var(--color-surface); color: var(--color-ink); box-shadow: var(--shadow-card); }
.seg button:focus-visible { outline: 2px solid var(--color-focus); outline-offset: 0; }
.seg button:disabled { opacity: 0.55; cursor: not-allowed; }

/* ---------- tabs ---------- */
.tabs { display: flex; gap: var(--space-2xs); border-bottom: var(--rule-hair) solid var(--color-rule); overflow-x: auto; scrollbar-width: none; }
.tab {
  position: relative; min-height: var(--control-h); padding: 0 var(--space-md); border: 0; background: transparent;
  color: var(--color-muted); font-size: var(--text-sm); font-weight: 500; line-height: 1; white-space: nowrap; cursor: pointer;
  transition: color var(--dur-micro) var(--ease-out);
}
.tab::after { content: ""; position: absolute; inset: auto var(--space-sm) 0; height: 2px; background: var(--color-accent); transform: scaleX(0); transition: transform var(--dur-short) var(--ease-out); }
@media (hover: hover) { .tab:hover { color: var(--color-ink); } }
.tab:active { color: var(--color-ink-2); }
.tab[aria-selected="true"] { color: var(--color-ink); }
.tab[aria-selected="true"]::after { transform: scaleX(1); }
.tab:focus-visible { outline: 2px solid var(--color-focus); outline-offset: -2px; border-radius: var(--radius-input); }
.tab:disabled { opacity: 0.55; cursor: not-allowed; }
.tab-panel { padding-top: var(--space-lg); }

/* ---------- panel (the one container) ---------- */
.panel { min-width: 0; color: var(--color-ink); border: var(--rule-hair) solid var(--color-rule); border-radius: var(--radius-card); background: var(--color-surface); box-shadow: var(--shadow-card); }
@supports (corner-shape: bevel) { .panel { border-radius: var(--cut-l) var(--radius-mark); corner-shape: bevel round; } }
.panel__head { display: flex; align-items: center; gap: var(--space-sm); padding: var(--space-sm) var(--space-md); border-bottom: var(--rule-hair) solid var(--color-rule); }
.panel__title { font-size: var(--text-md); font-weight: 600; letter-spacing: 0; }
.panel__actions { margin-left: auto; display: flex; align-items: center; gap: var(--space-2xs); }
.panel__body { padding: var(--space-md); }
.panel__foot { display: flex; align-items: center; gap: var(--space-xs); padding: var(--space-sm) var(--space-md); border-top: var(--rule-hair) solid var(--color-rule); }

/* ---------- status label ---------- */
.status { display: inline-flex; align-items: center; gap: var(--space-2xs); font-size: var(--text-sm); font-weight: 500; line-height: 1.2; white-space: nowrap; color: var(--color-muted); }
.status svg { width: 14px; height: 14px; }
.status--active { color: var(--color-accent-text); }
.status--frozen { color: var(--color-frozen); }
.status--cancelled { color: var(--color-muted); }

/* ---------- notices, empty, loading ---------- */
.notice { display: flex; align-items: flex-start; gap: var(--space-xs); padding: var(--space-sm) var(--space-md); border-radius: var(--radius-inner); background: var(--color-paper-3); color: var(--color-ink); font-size: var(--text-sm); }
.notice svg { width: 16px; height: 16px; margin-top: var(--space-3xs); }
.notice--error { background: var(--color-error-wash); }
.notice--error svg { color: var(--color-error); }
.empty { display: grid; justify-items: start; gap: var(--space-sm); padding: var(--space-xl) var(--space-lg); border: var(--rule-hair) dashed var(--color-rule-2); border-radius: var(--radius-card); color: var(--color-ink-2); }
.skeleton { display: block; min-height: 1lh; border-radius: var(--radius-mark); background: var(--color-paper-3); animation: sp-pulse 1.4s var(--ease-in-out) infinite alternate; }
@keyframes sp-pulse { from { opacity: 1; } to { opacity: 0.45; } }
.meta { color: var(--color-muted); font-size: var(--text-sm); }

/* ---------- chat session ---------- */
.chat { display: grid; gap: var(--space-md); margin: 0; padding: 0; list-style: none; }
.msg { display: grid; gap: var(--space-2xs); min-width: 0; }
.msg__who { display: inline-flex; align-items: center; gap: var(--space-2xs); color: var(--color-muted); font-size: var(--text-xs); font-weight: 500; }
.msg__who svg { width: 14px; height: 14px; color: var(--color-accent-text); }
.msg__body { min-width: 0; font-size: var(--text-sm); line-height: 1.65; }
.msg__body > * + * { margin-top: var(--space-xs); }
.msg__body a { color: var(--color-accent-text); }
.msg__body .url { font-family: var(--font-mono); font-size: var(--text-xs); word-break: break-all; }
.msg--agent .msg__body { color: var(--color-ink); }
.msg--user { justify-items: end; }
.msg--user .msg__body { max-width: 85%; padding: var(--space-xs) var(--space-sm); border-radius: var(--radius-inner) var(--radius-inner) var(--space-3xs) var(--radius-inner); background: var(--color-accent-wash); color: var(--color-ink); }
.composer { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: end; gap: var(--space-xs); }
.composer .textarea { min-height: var(--control-h); height: auto; field-sizing: content; max-height: 10lh; }

/* ---------- gallery (link and image previews) ---------- */
.gallery { display: grid; gap: var(--space-xs); min-width: 0; container-type: inline-size; }
.gallery__bar { display: flex; align-items: center; gap: var(--space-xs); }
.gallery__bar .seg, .gallery__bar .btn-row { margin-left: auto; }
.gallery__track { display: grid; gap: var(--space-sm); margin: 0; padding: 0; list-style: none; }
.gallery__track[data-view="grid"] { grid-template-columns: repeat(3, minmax(0, 1fr)); }
@container (max-width: 420px) { .gallery__track[data-view="grid"] { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.gallery__track[data-view="slide"] { grid-auto-flow: column; grid-auto-columns: minmax(0, 78%); overflow-x: auto; overscroll-behavior-x: contain; scroll-snap-type: x mandatory; scrollbar-width: thin; padding-bottom: var(--space-2xs); }
.gallery__track[data-view="slide"] > li { scroll-snap-align: start; }
.preview { min-width: 0; }
.preview__link { display: grid; gap: var(--space-2xs); border-radius: var(--radius-inner); color: inherit; text-decoration: none; }
.preview__media { display: grid; place-items: center; aspect-ratio: 16 / 10; overflow: hidden; border-radius: var(--radius-inner); background: var(--color-paper-3); color: var(--color-muted); outline: var(--rule-hair) solid var(--color-rule); outline-offset: calc(var(--rule-hair) * -1); }
.preview__media img { width: 100%; height: 100%; object-fit: cover; }
.preview__media svg { width: 24px; height: 24px; }
.preview__title { display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; overflow: hidden; font-size: var(--text-sm); font-weight: 500; line-height: 1.4; }
.preview__site { overflow: hidden; color: var(--color-muted); font-size: var(--text-xs); text-overflow: ellipsis; white-space: nowrap; }
@media (hover: hover) { .preview__link:hover .preview__title { text-decoration: underline; text-decoration-color: var(--color-accent); } }
.preview__link:focus-visible { outline: 2px solid var(--color-focus); outline-offset: 2px; }

/* ---------- markdown document ---------- */
.md-doc { max-width: 72ch; color: var(--color-ink); font-size: var(--text-md); line-height: 1.75; }
.md-doc > * + * { margin-top: var(--space-md); }
.md-doc h1 { font-size: var(--text-3xl); line-height: 1.25; }
.md-doc h2 { margin-top: var(--space-xl); padding-bottom: var(--space-xs); border-bottom: var(--rule-hair) solid var(--color-rule); font-size: var(--text-xl); }
.md-doc h3 { margin-top: var(--space-lg); font-size: var(--text-lg); }
.md-doc h4 { margin-top: var(--space-lg); font-size: var(--text-md); }
.md-doc h2 + *, .md-doc h3 + *, .md-doc h4 + * { margin-top: var(--space-sm); }
.md-doc ul, .md-doc ol { padding-left: var(--space-lg); }
.md-doc li + li { margin-top: var(--space-2xs); }
.md-doc li::marker { color: var(--color-muted); }
.md-doc a { color: var(--color-accent-text); }
.md-doc strong { font-weight: 600; }
.md-doc blockquote { margin-inline: 0; padding: var(--space-2xs) var(--space-md); border-left: 2px solid var(--color-rule-2); color: var(--color-ink-2); }
.md-doc code { padding: var(--space-3xs) var(--space-2xs); border-radius: var(--radius-mark); background: var(--color-paper-3); font-size: 0.875em; }
.md-doc pre { overflow-x: auto; padding: var(--space-md); border-radius: var(--radius-inner); background: var(--color-graphite); color: var(--color-graphite-ink); font-size: var(--text-sm); line-height: 1.6; }
.md-doc pre code { padding: 0; background: none; font-size: inherit; color: inherit; }
.md-doc img { border-radius: var(--radius-inner); background: var(--color-paper-3); outline: var(--rule-hair) solid var(--color-rule); outline-offset: calc(var(--rule-hair) * -1); }
.md-doc figure { margin-inline: 0; }
.md-doc figcaption { margin-top: var(--space-xs); color: var(--color-muted); font-size: var(--text-sm); }
.md-doc table { width: 100%; border-collapse: collapse; font-size: var(--text-sm); line-height: 1.55; }
.md-doc th, .md-doc td { padding: var(--space-xs) var(--space-sm); border-bottom: var(--rule-hair) solid var(--color-rule); text-align: left; vertical-align: top; }
.md-doc th { border-bottom-color: var(--color-rule-2); font-weight: 600; white-space: nowrap; }
.md-doc hr { margin-block: var(--space-xl); border: 0; border-top: var(--rule-hair) solid var(--color-rule); }

/* ---------- reduced motion ---------- */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; scroll-behavior: auto !important; }
  .btn:active, .chip:active, .chip:has(input:checked), .chip[aria-pressed="true"] { transform: none; }
  .skeleton { animation: none; }
